function buildDomContext() {
  try {
    var snapshot = inspectRoamDom();
    return {
      snapshot: snapshot,
      text: formatSnapshotForPrompt(snapshot)
    };
  } catch (e) {
    console.warn("[Live Themes] DOM snapshot failed", e);
    return null;
  }
}

/** Downloads the full snapshot as JSON and logs it (learning phase). */
function exportDomSnapshot() {
  var snapshot = inspectRoamDom();
  var json = JSON.stringify(snapshot, null, 2);
  console.log("[Live Themes] DOM snapshot", snapshot);
  console.log("[Live Themes] DOM anatomy\n\n" + snapshot.anatomy.filter(function (a) {
    return !a.missing;
  }).map(function (a) {
    return "## ".concat(a.label, " (").concat(a.selector, ", ").concat(a.count, " on screen)\n").concat(a.ancestors.join(" > "), "\n").concat(a.tree.join("\n"));
  }).join("\n\n"));
  try {
    var blob = new Blob([json], {
      type: "application/json"
    });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = "live-themes-dom-snapshot-".concat(snapshot.at.slice(0, 19).replace(/[:T]/g, "-"), ".json");
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () {
      return URL.revokeObjectURL(url);
    }, 1000);
  } catch (e) {
    console.warn("[Live Themes] snapshot download failed", e);
  }
  return snapshot;
}

